  always_comb begin
    case (state)
      A: next_state = w ? B : A;
      B: next_state = w ? C : D;
      C: next_state = w ? E : D;
      D: next_state = w ? F : A;
      E: next_state = w ? E : D;
      F: next_state = w ? C : D;
      default: next_state = A;
    endcase
  end

  always_ff @(posedge clk) begin
    if (reset) state <= A;
    else state <= next_state;
  end

  assign z = (state == E) || (state == F);

endmodule

